fn pubkey(&self) -> Address {
    Address::from(self.0.verifying_key().to_bytes())
}

pub fn try_compile_with_config(
    payer: &Address,
    instructions: &[Instruction],
    recent_blockhash: Hash,
    config: TransactionConfig,
) -> Result<Self, CompileError> {
    let compiled_keys = CompiledKeys::compile(instructions, Some(*payer));
    let (header, static_keys) = compiled_keys.try_into_message_components()?;

    let account_keys = AccountKeys::new(&static_keys, None);
    let instructions = account_keys.try_compile_instructions(instructions)?;

    Ok(Self {
        header,
        config,
        lifetime_specifier: recent_blockhash,
        account_keys: static_keys,
        instructions,
    })
}

pub fn format_err(args: Arguments) -> Error {
    if let Some(message) = args.as_str() {
        // anyhow!("literal"), can downcast to &'static str
        Error::msg(message)
    } else {
        // anyhow!("interpolate {var}"), can downcast to String
        Error::msg(fmt::format(args))
    }
}

fn from_str(s: &str) -> Result<Self, Self::Err> {
    use five8::DecodeError;
    if s.len() > MAX_BASE58_LEN {
        return Err(ParsePubkeyError::WrongSize);
    }
    let mut bytes = [0; PUBKEY_BYTES];
    five8::decode_32(s, &mut bytes).map_err(|e| match e {
        DecodeError::InvalidChar(_) => ParsePubkeyError::Invalid,
        DecodeError::TooLong
        | DecodeError::TooShort
        | DecodeError::LargestTermTooHigh
        | DecodeError::OutputTooLong => ParsePubkeyError::WrongSize,
    })?;
    Ok(Pubkey(bytes))
}

