pub fn decode_pool_v1_pair_forest_checkpoint_v1(
    bytes: &[u8],
) -> Result<PoolV1PairForestCheckpointV1, PoolV1PairForestAccountErrorV1> {
    if bytes.len() != POOL_V1_PAIR_FOREST_CHECKPOINT_ACCOUNT_BYTES {
        return Err(PoolV1PairForestAccountErrorV1::WrongLength);
    }
    if bytes[..4] != POOL_V1_PAIR_FOREST_CHECKPOINT_MAGIC {
        return Err(PoolV1PairForestAccountErrorV1::WrongMagic);
    }
    if bytes[4] != POOL_V1_PAIR_FOREST_CHECKPOINT_VERSION {
        return Err(PoolV1PairForestAccountErrorV1::WrongVersion);
    }
    if bytes[5] != POOL_V1_PAIR_FOREST_LANE_COUNT as u8 {
        return Err(PoolV1PairForestAccountErrorV1::WrongLaneCount);
    }
    if bytes[6] != POOL_V1_DIGEST_ENCODING_VERSION {
        return Err(PoolV1PairForestAccountErrorV1::WrongDigestEncoding);
    }
    if bytes[176..].iter().any(|byte| *byte != 0) {
        return Err(PoolV1PairForestAccountErrorV1::NonZeroReserved);
    }
    let master: [u8; 32] = bytes[CHECKPOINT_MASTER_OFFSET..CHECKPOINT_DOMAIN_OFFSET]
        .try_into()
        .unwrap();
    let deployment_domain: [u8; 32] = bytes[CHECKPOINT_DOMAIN_OFFSET..CHECKPOINT_SEQUENCE_OFFSET]
        .try_into()
        .unwrap();
    if master == [0u8; 32] || deployment_domain == [0u8; 32] {
        return Err(PoolV1PairForestAccountErrorV1::ZeroRequiredBinding);
    }
    let global_root = decode_digest_canonical(
        bytes[CHECKPOINT_GLOBAL_ROOT_OFFSET..CHECKPOINT_LANE_SEQUENCES_OFFSET]
            .try_into()
            .unwrap(),
    )
    .map_err(|_| PoolV1PairForestAccountErrorV1::NonCanonicalDigest)?;
    let mut lane_sequences = [0u64; POOL_V1_PAIR_FOREST_LANE_COUNT];
    for (lane, sequence) in lane_sequences.iter_mut().enumerate() {
        let start = CHECKPOINT_LANE_SEQUENCES_OFFSET + 8 * lane;
        *sequence = u64::from_le_bytes(bytes[start..start + 8].try_into().unwrap());
        if *sequence > POOL_V1_PAIR_CAPACITY {
            return Err(PoolV1PairForestAccountErrorV1::InvalidMasterState);
        }
    }
    Ok(PoolV1PairForestCheckpointV1 {
        bump: bytes[7],
        master,
        deployment_domain,
        checkpoint_sequence: u64::from_le_bytes(
            bytes[CHECKPOINT_SEQUENCE_OFFSET..CHECKPOINT_GLOBAL_ROOT_OFFSET]
                .try_into()
                .unwrap(),
        ),
        global_root,
        lane_sequences,
    })
}

pub fn single_output(first_commitment: Digest) -> Result<Self, PoolV1PairLeafErrorV1> {
    let result = Self {
        first_commitment,
        second_occupied: M31::ZERO,
        second_commitment: [M31::ZERO; 8],
        second_occupancy_inverse: M31::ZERO,
    };
    result.validate()?;
    Ok(result)
}

pub fn leaf_digest(&self) -> Result<Digest, PoolV1PairLeafErrorV1> {
    self.validate()?;
    Ok(pool_v1_tree_parent(
        &self.first_commitment,
        &self.second_commitment,
    ))
}

pub fn compile_pool_v1_pair_forest_withdrawal_merged_c1_v1(
    public: &PoolV1WithdrawalPublicV1,
    witness: &PoolV1PairForestWithdrawalWitnessV1,
    context: PoolV1PaymentRelationContextV1<'_>,
    snapshot: PoolV1PairLiveSnapshotV1,
) -> Result<PoolV1PairForestMergedC1CompilationV1, PoolV1PairTraceErrorV1> {
    let lane_anchor = lane_root(&witness.input.pair)?;
    let temporary_public = PoolV1WithdrawalPublicV1 {
        anchor_root: lane_anchor,
        ..*public
    };
    validate_pool_v1_withdrawal_public_v1(&temporary_public)
        .map_err(PoolV1PairTraceErrorV1::Statement)?;
    validate_common(
        temporary_public.pool,
        temporary_public.deployment_domain,
        temporary_public.anchor_sequence,
        temporary_public.anchor_root,
        temporary_public.nullifier,
        temporary_public.asset_id,
        &witness.input.pair,
        temporary_context(context, lane_anchor),
    )?;
    if snapshot.pool != public.pool || snapshot.deployment_domain != public.deployment_domain {
        return Err(PoolV1PairTraceErrorV1::SnapshotBindingMismatch);
    }
    if witness.change.value == 0
        || witness.change.value >= VALUE_LIMIT
        || public.amount.checked_add(witness.change.value) != Some(witness.input.pair.value)
    {
        return Err(PoolV1PairTraceErrorV1::Conservation);
    }
    compile_forest_from_copies(
        &witness.input,
        public.amount,
        None,
        &witness.change,
        ForestPublic {
            anchor: public.anchor_root,
            nullifier: public.nullifier,
            recipient_commitment: None,
            change_commitment: public.change_commitment,
            asset: public.asset_id,
        },
        lane_anchor,
        snapshot,
    )
}

pub fn compile_pool_v1_pair_forest_private_transfer_merged_c1_v1(
    public: &PoolV1PrivateTransferPublicV1,
    witness: &PoolV1PairForestPrivateTransferWitnessV1,
    context: PoolV1PaymentRelationContextV1<'_>,
    snapshot: PoolV1PairLiveSnapshotV1,
) -> Result<PoolV1PairForestMergedC1CompilationV1, PoolV1PairTraceErrorV1> {
    let lane_anchor = lane_root(&witness.input.pair)?;
    let temporary_public = PoolV1PrivateTransferPublicV1 {
        anchor_root: lane_anchor,
        ..*public
    };
    validate_pool_v1_private_transfer_public_v1(&temporary_public)
        .map_err(PoolV1PairTraceErrorV1::Statement)?;
    validate_common(
        temporary_public.pool,
        temporary_public.deployment_domain,
        temporary_public.anchor_sequence,
        temporary_public.anchor_root,
        temporary_public.nullifier,
        temporary_public.asset_id,
        &witness.input.pair,
        temporary_context(context, lane_anchor),
    )?;
    if snapshot.pool != public.pool || snapshot.deployment_domain != public.deployment_domain {
        return Err(PoolV1PairTraceErrorV1::SnapshotBindingMismatch);
    }
    if witness.recipient.value == 0
        || witness.change.value == 0
        || witness.recipient.value >= VALUE_LIMIT
        || witness.change.value >= VALUE_LIMIT
        || witness.recipient.value.checked_add(witness.change.value)
            != Some(witness.input.pair.value)
    {
        return Err(PoolV1PairTraceErrorV1::Conservation);
    }
    compile_forest_from_copies(
        &witness.input,
        witness.recipient.value,
        Some(&witness.recipient),
        &witness.change,
        ForestPublic {
            anchor: public.anchor_root,
            nullifier: public.nullifier,
            recipient_commitment: Some(public.recipient_commitment),
            change_commitment: public.change_commitment,
            asset: public.asset_id,
        },
        lane_anchor,
        snapshot,
    )
}

pub fn encode_pool_v1_pair_forest_terminal_statement_v1(
    statement: &PoolV1PairForestTerminalStatementV1,
) -> Result<[u8; POOL_V1_PAIR_FOREST_TERMINAL_STATEMENT_BYTES], PoolV1PairForestTerminalFormatErrorV1>
{
    validate_pool_v1_pair_forest_terminal_statement_v1(statement)?;
    let common = statement.common();
    let mut output = [0u8; POOL_V1_PAIR_FOREST_TERMINAL_STATEMENT_BYTES];
    output[..4].copy_from_slice(&POOL_V1_PAIR_FOREST_TERMINAL_STATEMENT_MAGIC);
    output[4] = POOL_V1_PAIR_FOREST_TERMINAL_VERSION;
    output[5] = statement.transition_kind() as u8;
    output[6] = POOL_V1_DIGEST_ENCODING_VERSION;
    output[7] = common.output_lane;
    output[MASTER_OFFSET..CHECKPOINT_ACCOUNT_OFFSET].copy_from_slice(&common.master_account);
    output[CHECKPOINT_ACCOUNT_OFFSET..SELECTED_LANE_ACCOUNT_OFFSET]
        .copy_from_slice(&common.checkpoint_account);
    output[SELECTED_LANE_ACCOUNT_OFFSET..CHECKPOINT_SEQUENCE_OFFSET]
        .copy_from_slice(&common.selected_lane_account);
    output[CHECKPOINT_SEQUENCE_OFFSET..HISTORICAL_ANCHOR_OFFSET]
        .copy_from_slice(&common.checkpoint_sequence.to_le_bytes());
    output[HISTORICAL_ANCHOR_OFFSET..LATE_STATEMENT_OFFSET]
        .copy_from_slice(&encode_digest_canonical(&common.historical_global_anchor));
    encode_pool_v1_pair_late_public_statement_v1(
        &common.lane_transition,
        &mut output[LATE_STATEMENT_OFFSET..PAYMENT_STATEMENT_OFFSET],
    )
    .map_err(|error| PoolV1PairForestTerminalFormatErrorV1::LaneTransition(error))?;
    let payment = match statement {
        PoolV1PairForestTerminalStatementV1::PrivateTransfer { public, .. } => {
            encode_pool_v1_private_transfer_public_v1(public)
        }
        PoolV1PairForestTerminalStatementV1::Withdrawal { public, .. } => {
            encode_pool_v1_withdrawal_public_v1(public)
        }
    }
    .map_err(|error| PoolV1PairForestTerminalFormatErrorV1::Payment(error))?;
    output[PAYMENT_STATEMENT_OFFSET..].copy_from_slice(&payment);
    Ok(output)
}

pub fn semantic_public(&self) -> super::pair_forest_semantic_terminal::r0::Public<'_> {
    use super::pair_forest_semantic_terminal::r0::Public;
    match self {
        Self::PrivateTransfer { common, public } => {
            Public::Transfer(public, &common.lane_transition)
        }
        Self::Withdrawal { common, public } => {
            Public::Withdrawal(public, &common.lane_transition)
        }
    }
}

pub fn encode_pool_v1_pair_verified_afterstate_v1(
    afterstate: &PoolV1PairVerifiedAfterstateV1,
) -> Result<[u8; POOL_V1_PAIR_VERIFIED_AFTERSTATE_BYTES], PoolV1PairVerifierTransportErrorV1> {
    validate_verified_afterstate(afterstate)?;
    let mut output = [0u8; POOL_V1_PAIR_VERIFIED_AFTERSTATE_BYTES];
    output[..4].copy_from_slice(&POOL_V1_PAIR_VERIFIED_AFTERSTATE_MAGIC);
    output[4] = POOL_V1_PAIR_VERIFIER_TRANSPORT_VERSION;
    output[5] = super::POOL_V1_PAIR_TREE_STORAGE_FORMAT_VERSION;
    output[6] = POOL_V1_DIGEST_ENCODING_VERSION;
    output[7] = 1;
    output[8..16].copy_from_slice(&afterstate.next_pair_index.to_le_bytes());
    output[16..48].copy_from_slice(&encode_digest_canonical(&afterstate.next_root));
    for (level, node) in afterstate.next_frontier.iter().enumerate() {
        let start = 48 + 32 * level;
        output[start..start + 32].copy_from_slice(&encode_digest_canonical(node));
    }
    Ok(output)
}

pub fn pool_v1_pair_forest_terminal_bump_hints_v1(
    program_id: &Pubkey,
    master: &Pubkey,
    lane: &Pubkey,
    next_leaf_index: u64,
    withdrawal: bool,
) -> PoolV1PairForestTerminalBumpHintsV1 {
    let current = root_history_location(next_leaf_index);
    let next = root_history_location(next_leaf_index + 1);
    let current_page = pool_v1_root_page_address(program_id, lane, current.page_number).1;
    let next_page = if current.page_number == next.page_number {
        0
    } else {
        pool_v1_root_page_address(program_id, lane, next.page_number).1
    };
    let (vault_authority, vault_token_account) = if withdrawal {
        (
            crate::vault::pool_v1_vault_authority_address(program_id, master).1,
            crate::vault::pool_v1_vault_token_account_address(program_id, master).1,
        )
    } else {
        (0, 0)
    };
    PoolV1PairForestTerminalBumpHintsV1 {
        current_page,
        next_page,
        vault_authority,
        vault_token_account,
    }
}

pub fn encode_pool_v1_pair_forest_terminal_request_v1(
    request: &PoolV1PairForestTerminalRequestV1,
) -> Result<[u8; POOL_V1_PAIR_FOREST_TERMINAL_REQUEST_BYTES], PoolV1PairForestTerminalFormatErrorV1>
{
    if request.verifier_profile == [0u8; 32]
        || request.verifier_release == [0u8; 32]
        || request.pool_program == [0u8; 32]
    {
        return Err(PoolV1PairForestTerminalFormatErrorV1::NonZeroBinding);
    }
    let payment = match request.public {
        PoolV1PairForestTerminalPaymentV1::PrivateTransfer(public) => {
            encode_pool_v1_private_transfer_public_v1(&public)
        }
        PoolV1PairForestTerminalPaymentV1::Withdrawal(public) => {
            encode_pool_v1_withdrawal_public_v1(&public)
        }
    }
    .map_err(PoolV1PairForestTerminalFormatErrorV1::Payment)?;
    let mut output = [0u8; POOL_V1_PAIR_FOREST_TERMINAL_REQUEST_BYTES];
    output[..4].copy_from_slice(&POOL_V1_PAIR_FOREST_TERMINAL_REQUEST_MAGIC);
    output[4] = POOL_V1_PAIR_FOREST_TERMINAL_VERSION;
    output[5] = request.public.transition_kind() as u8;
    output[6] = POOL_V1_DIGEST_ENCODING_VERSION;
    output[REQUEST_PROFILE_OFFSET..REQUEST_RELEASE_OFFSET]
        .copy_from_slice(&request.verifier_profile);
    output[REQUEST_RELEASE_OFFSET..REQUEST_POOL_PROGRAM_OFFSET]
        .copy_from_slice(&request.verifier_release);
    output[REQUEST_POOL_PROGRAM_OFFSET..REQUEST_PAYMENT_OFFSET]
        .copy_from_slice(&request.pool_program);
    output[REQUEST_PAYMENT_OFFSET..].copy_from_slice(&payment);
    Ok(output)
}

pub fn encode_pair_forest_terminal_instruction_data_v1(
    request: &[u8],
    hints: PoolV1PairForestTerminalBumpHintsV1,
) -> Vec<u8> {
    let mut data = Vec::with_capacity(request.len() + POOL_V1_PAIR_FOREST_TERMINAL_BUMP_HINT_BYTES);
    data.extend_from_slice(request);
    data.extend_from_slice(&hints.encode());
    data
}

pub fn pool_v1_pair_forest_nullifier_marker_address(
    program_id: &Pubkey,
    master: &Pubkey,
    canonical_nullifier_encoding: &[u8; 32],
) -> Result<(Pubkey, [u8; 32]), ProgramError> {
    decode_digest_canonical(canonical_nullifier_encoding)
        .map_err(|_| PoolV1ProgramError::InvalidNullifierMarkerAccount)?;
    let seed = pool_v1_pair_forest_marker_seed_v1(master, canonical_nullifier_encoding);
    let address = Pubkey::create_with_seed(
        master,
        pool_v1_pair_forest_marker_seed_str_v1(&seed)?,
        program_id,
    )
    .map_err(|_| PoolV1ProgramError::InvalidNullifierMarkerAddress)?;
    Ok((address, seed))
}

pub const fn as_secs_f64(&self) -> f64 {
    (self.secs as f64) + (self.nanos.as_inner() as f64) / (NANOS_PER_SEC as f64)
}

pub const fn div_ceil(self, rhs: Self) -> Self {
    let d = self / rhs;
    let r = self % rhs;
    if r > 0 {
        d + 1
    } else {
        d
    }
}

pub const fn len(&self) -> usize {
    self.as_bytes().len()
}

pub fn pool_v1_pair_forest_lane_address(
    program_id: &Pubkey,
    master: &Pubkey,
    lane_id: u8,
) -> Result<(Pubkey, u8), ProgramError> {
    if usize::from(lane_id) >= POOL_V1_PAIR_FOREST_LANE_COUNT {
        return Err(ProgramError::InvalidSeeds);
    }
    Ok(Pubkey::find_program_address(
        &[POOL_V1_PAIR_FOREST_LANE_SEED, master.as_ref(), &[lane_id]],
        program_id,
    ))
}

#[derive(Clone, Copy, Default, Eq, Ord, PartialEq, PartialOrd)]
#[cfg_attr(feature = "dev-context-only-utils", derive(Arbitrary))]
pub struct Pubkey(pub(crate) [u8; 32]);

/// Custom impl of Hash for Pubkey
/// allows us to skip hashing the length of the pubkey
/// which is always the same anyway
impl Hash for Pubkey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        state.write(self.as_array());
    }
}

pub fn pool_v1_tree_parent(left: &Digest, right: &Digest) -> Digest {
    merkle_node_compress_v3(left, right)
}

pub const fn from_str_radix(src: &str, radix: u32) -> Result<$int_ty, ParseIntError> {
    <$int_ty>::from_ascii_radix(src.as_bytes(), radix)
}
